/*
 * A357947  Number of "tertian" musical chords generated by stacking m minor
 *          or major thirds with no allowance of repetition of notes.
 * https://oeis.org/A357947
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   a(n) = number of strings of length n over {3,4} with all *
 *            prefix sums modulo 12 distinct and never 0 after the first step
 * Range:     u8 n <= 12, u16 n <= 12, u32 n <= 12, u64 n <= 12, u128 n <= 12,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <string.h>

#define STATES 12
#define MASKS (1 << STATES)

/* Return a(n) as described.  Results for n > 12 are 0. */
seq_t a(idx_t n)
{
    static seq_t cache[13] = {0};   /* cache[0..12] */
    static bool ready = false;

    if (!ready) {
        ready = true;
        static seq_t curr[MASKS][STATES];
        static seq_t next[MASKS][STATES];
        memset(curr, 0, sizeof(curr));
        curr[1][0] = 1;           /* start at note 0, visited mask 1<<0 */
        cache[0] = 1;

        for (int len = 1; len <= 11; ++len) {
            memset(next, 0, sizeof(next));
            for (int mask = 0; mask < MASKS; ++mask) {
                for (int state = 0; state < STATES; ++state) {
                    seq_t val = curr[mask][state];
                    if (!val) continue;

                    int ns = (state + 3) % 12;
                    if (!(mask & (1 << ns))) {
                        int new_mask = mask | (1 << ns);
                        next[new_mask][ns] += val;
                    }

                    ns = (state + 4) % 12;
                    if (!(mask & (1 << ns))) {
                        int new_mask = mask | (1 << ns);
                        next[new_mask][ns] += val;
                    }
                }
            }

            seq_t sum = 0;
            for (int mask = 0; mask < MASKS; ++mask)
                for (int state = 0; state < STATES; ++state)
                    sum += next[mask][state];
            cache[len] = sum;

            memcpy(curr, next, sizeof(curr));
        }
        /* cache[12] is already 0 */
    }

    return (n < 13) ? cache[(size_t)n] : 0;
}
